(()=>{const c=COMPACT_SYSTEM_CONFIG;c.effects.message=(playing,dark,visible)=>({type:'long-thanh-effect',playing,dark,visible});c.slides={defs:c.slidesData.map(x=>[x.id,x.title]),gallery:()=>c.slidesData.map(x=>`<article class="slide-record" id="${x.id}" data-composition-id="${x.id}"><h3>${x.title}</h3><div class="slide-shell canvas-wrap"><div class="s283-canvas ${x.applicationGroup}" data-slide283="${x.id}">${x.nativeHTML.replaceAll('../illustrations/','assets/illustrations/').replaceAll('../charts/','assets/charts/').replaceAll('../icons/','assets/icons/')}</div></div><p class="note">Mẫu trống/giả lập; hình học không phải ảnh sản phẩm. Đổi nội dung, giữ điều kiện và nguồn.</p><button data-compact-copy="${x.id}">Tái sử dụng</button></article>`).join('')};c.logo=register=>{register('logo-pair','Logo nguồn Long Thành','Giữ nguyên tệp, màu và tỷ lệ.','logo',{source:'assets/identity/logo_nhựa long thành.png'});return `<section class="section" id="logo-pair"><h2>Logo nguồn</h2><div class="rule"><img style="height:200px;width:auto;max-width:100%;object-fit:contain;background:white" src="assets/identity/logo_nhựa long thành.png" alt="Logo gốc Nhựa Long Thành"><p>Giữ nguyên dấu 405, chữ, tỷ lệ và màu. Không vẽ lại hoặc biến logo thành icon chức năng.</p><p>Khoảng trống và cỡ tối thiểu trong bản triển khai là đề xuất; chưa có quy chuẩn nguồn cho các số đo đó.</p><button data-compact-copy="logo-pair">Tái sử dụng</button></div></section>`};c.direction=(section,register)=>'';c.decorate=root=>{CompactDesignGuidelines.decorate(root,c)};})();
COMPACT_SYSTEM_CONFIG.counts=root=>({websites:root.querySelectorAll("#websites [data-library-id]").length,apps:root.querySelectorAll("#apps [data-library-id]").length,reading:root.querySelectorAll("#reading > .compact-extracted > .compact-fragment").length+root.querySelectorAll("#reading .app-grid > .card").length});

COMPACT_SYSTEM_CONFIG.resolveNode=id=>document.getElementById(SYSTEM_DATA.semanticAliases?.[id]?.canonicalId||id);














